import{_ as o,c as s,o as i,j as a,Y as r,t as n}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"git-sh-setup | x-cmd man (git man1) | Common Git shell script setup code","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-sh-setup - Common Git shell script setup code","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-sh-setup | x-cmd man (git man1) | Common Git shell script setup code"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-sh-setup - Common Git shell script setup code"}]]},"headers":[],"params":{"isMan":true,"man":"git-sh-setup","category":"git man1","desc":"Common Git shell script setup code"},"relativePath":"git/man1/git-sh-setup.md","filePath":"git/man1/[man].md"}'),p={name:"git/man1/git-sh-setup.md"},l={class:"visually-hidden"};function h(t,e,c,d,u,g){return i(),s("div",null,[a("h1",l,n(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-sh-setup - Common Git shell script setup code</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exec-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)/git-sh-setup&quot;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This is not a command the end user would want to run. Ever. This documentation is meant for people who are studying the Porcelain-ish scripts and/or are writing new ones.</p><p>The <em>git sh-setup</em> scriptlet is designed to be sourced (using <strong>.</strong>) by other shell scripts to set up some variables pointing at the normal Git directories and a few helper shell functions.</p><p>Before sourcing it, your script should set up a few variables; <strong>USAGE</strong> (and <strong>LONG_USAGE</strong>, if any) is used to define message given by <strong>usage()</strong> shell function. <strong>SUBDIRECTORY_OK</strong> can be set if the script can run from a subdirectory of the working tree (some commands do not).</p><p>The scriptlet sets <strong>GIT_DIR</strong> and <strong>GIT_OBJECT_DIRECTORY</strong> shell variables, but does <strong>not</strong> export them to the environment.</p><h2 id="functions" tabindex="-1">FUNCTIONS <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;FUNCTIONS&quot;">​</a></h2><p>die</p><blockquote><p>exit after emitting the supplied error message to the standard error stream.</p></blockquote><p>usage</p><blockquote><p>die with the usage message.</p></blockquote><p>set_reflog_action</p><blockquote><p>Set <strong>GIT_REFLOG_ACTION</strong> environment to a given string (typically the name of the program) unless it is already set. Whenever the script runs a <strong>git</strong> command that updates refs, a reflog entry is created using the value of this string to leave the record of what command updated the ref.</p></blockquote><p>git_editor</p><blockquote><p>runs an editor of user&#39;s choice (GIT_EDITOR, core.editor, VISUAL or EDITOR) on a given file, but error out if no editor is specified and the terminal is dumb.</p></blockquote><p>is_bare_repository</p><blockquote><p>outputs <strong>true</strong> or <strong>false</strong> to the standard output stream to indicate if the repository is a bare repository (i.e. without an associated working tree).</p></blockquote><p>cd_to_toplevel</p><blockquote><p>runs chdir to the toplevel of the working tree.</p></blockquote><p>require_work_tree</p><blockquote><p>checks if the current directory is within the working tree of the repository, and otherwise dies.</p></blockquote><p>require_work_tree_exists</p><blockquote><p>checks if the working tree associated with the repository exists, and otherwise dies. Often done before calling cd_to_toplevel, which is impossible to do if there is no working tree.</p></blockquote><p>require_clean_work_tree &lt;action&gt; [&lt;hint&gt;]</p><blockquote><p>checks that the working tree and index associated with the repository have no uncommitted changes to tracked files. Otherwise it emits an error message of the form <strong>Cannot &lt;action&gt;: &lt;reason&gt;. &lt;hint&gt;</strong>, and dies. Example:</p><blockquote><pre><code>require_clean_work_tree rebase &quot;Please commit or stash them.&quot;
</code></pre></blockquote></blockquote><p>get_author_ident_from_commit</p><blockquote><p>outputs code for use with eval to set the GIT_AUTHOR_NAME, GIT_AUTHOR_EMAIL and GIT_AUTHOR_DATE variables for a given commit.</p></blockquote><p>create_virtual_base</p><blockquote><p>modifies the first file so only lines in common with the second file remain. If there is insufficient common material, then the first file is left empty. The result is suitable as a virtual base input for a 3-way merge.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,34))])}const k=o(p,[["render",h]]);export{f as __pageData,k as default};
